using System.Diagnostics;using System.Text;using System.Threading.Tasks;using System;using System.IO;using System.Linq;using System.Threading;using System.Collections.Generic;using System.Web.Script.Serialization;
class InstallerCheck {
 static int checks;static void Check(bool value,string label){if(!value)throw new Exception(label);checks++;File.AppendAllText("installer-check.log","PASS "+label+Environment.NewLine);}static bool Rejected(string path){try{Setup.ValidateTarget(path);return false;}catch{return true;}}
 static int Main(){try{File.WriteAllText("installer-check.log","");string root=Path.GetFullPath("f-"+Guid.NewGuid().ToString("N").Substring(0,8));Directory.CreateDirectory(root);string target=Path.Combine(root,"自定义 目录","TV Studio");Check(Rejected(Path.GetPathRoot(root)),"drive root rejected before installation");string unrelated=Path.Combine(root,"unrelated");Directory.CreateDirectory(unrelated);File.WriteAllText(Path.Combine(unrelated,"notes.txt"),"keep");Check(Rejected(unrelated),"unrelated nonempty folder rejected");Check(Rejected(Setup.DataPath),"user data directory cannot become installation target");var percentages=new List<int>();var options=new InstallOptions{Target=target,Register=false,Desktop=false,StartMenu=false};var state=Setup.Install(options,p=>percentages.Add(p.Percent),CancellationToken.None);Check(File.Exists(Path.Combine(target,"TVStudio.exe"))&&File.Exists(Path.Combine(target,"Uninstall.exe")),"custom Unicode and spaced path installs real program and uninstaller");Check(percentages.First()>0&&percentages.Last()==100&&percentages.Zip(percentages.Skip(1),(a,b)=>b>=a).All(x=>x),"installation reports monotonic real extraction progress");using(var native=Process.Start(new ProcessStartInfo(Path.Combine(target,"tools","aapt.exe"),"dump badging "+"\""+Path.Combine(target,"apps","my-tv-0.apk")+"\""){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,StandardOutputEncoding=Encoding.UTF8,StandardErrorEncoding=Encoding.UTF8})){var output=native.StandardOutput.ReadToEndAsync();var errors=native.StandardError.ReadToEndAsync();if(!native.WaitForExit(30000)){native.Kill();throw new Exception("Native APK inspection timed out");}Task.WaitAll(output,errors);Check(native.ExitCode==0&&output.Result.Contains("com.lizongying.mytv0"),"native APK metadata works under custom Unicode installation path");}Check(state.Target==target&&Setup.IsInstalled(target),"installation manifest records selected target");Check(new FileInfo(Path.Combine(target,"Uninstall.exe")).Length<1024*1024,"standalone uninstaller does not duplicate full payload");string data=Path.Combine(root,"Data");Directory.CreateDirectory(data);File.WriteAllText(Path.Combine(data,"api-settings.txt"),"preserve");state=Setup.Install(options,p=>{},CancellationToken.None);Check(!string.IsNullOrEmpty(state.Backup)&&File.Exists(Path.Combine(state.Backup,"TVStudio.exe")),"overwrite upgrade preserves prior program backup");Check(File.ReadAllText(Path.Combine(data,"api-settings.txt"))=="preserve","overwrite preserves sibling user data");string cancelled=Path.Combine(root,"cancelled");var cancellation=new CancellationTokenSource();bool cancelledOk=false;try{Setup.Install(new InstallOptions{Target=cancelled,Register=false},p=>{if(p.Percent>=25&&!p.Committing)cancellation.Cancel();},cancellation.Token);}catch(OperationCanceledException){cancelledOk=true;}Check(cancelledOk&&!Directory.Exists(cancelled)&&!Directory.GetDirectories(root,"cancelled.new-*").Any(),"cancellation removes only staging files before commit");File.WriteAllText(Path.Combine(target,"my-notes.txt"),"user added file");Setup.Uninstall(target,false,p=>{});Check(!File.Exists(Path.Combine(target,"TVStudio.exe"))&&File.Exists(Path.Combine(target,"my-notes.txt")),"uninstall removes manifest files and preserves extra user files");Check(File.ReadAllText(Path.Combine(data,"api-settings.txt"))=="preserve"&&File.Exists(Path.Combine(unrelated,"notes.txt")),"uninstall leaves user data and unrelated folders untouched");using(var freeMutex=new Mutex(false,"Local\\XiaZheTengTVSetup")){string mutexTarget=Path.Combine(root,"mutex-target");using(var child=Process.Start(new ProcessStartInfo(typeof(Setup).Assembly.Location,"--test-target "+"\""+mutexTarget+"\""){UseShellExecute=false,CreateNoWindow=true})){if(!child.WaitForExit(30000)){child.Kill();throw new Exception("Installer mutex check timed out");}Check(child.ExitCode==0&&File.Exists(Path.Combine(mutexTarget,"TVStudio.exe")),"installer acquires an existing unowned mutex for relaunch");}}File.AppendAllText("installer-check.log",checks+" installer engine checks passed; no registry or shortcuts modified\n");return 0;}catch(Exception ex){File.AppendAllText("installer-check.log",ex.ToString());return 1;}}
}



